 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        cells.add(p)
                        stack.append(p)
            objects.append([color, cells])

    # Slide rigid objects right, letting leading objects move first.
    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        for r, c in cells:
            out[r][c] = color
    while True:
        moved = False
        for color, cells in sorted(objects, key=lambda obj: max(c for _, c in obj[1]), reverse=True):
            if all(c + 1 < w and out[r][c + 1] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = 0
                shifted = {(r, c + 1) for r, c in cells}
                for r, c in shifted:
                    out[r][c] = color
                # Keep the object geometry in sync for subsequent rounds.
                cells.clear()
                cells.update(shifted)
                moved = True
        if not moved:
            break
    return out
